@org.springframework.web.bind.annotation.RestController
@org.springframework.web.bind.annotation.RequestMapping("/api/auth")
class AuthController {

    private final AuthService authService;

    AuthController(AuthService authService) {
        this.authService = authService;
    }

    @org.springframework.web.bind.annotation.PostMapping("/register")
    @org.springframework.web.bind.annotation.ResponseStatus(org.springframework.http.HttpStatus.CREATED)
    RegisterResponse register(@org.springframework.web.bind.annotation.RequestBody @jakarta.validation.Valid RegisterRequest request) {
        return authService.register(request.email(), request.password(), request.fullName());
    }

    @org.springframework.web.bind.annotation.PostMapping("/login")
    TokenResponse login(@org.springframework.web.bind.annotation.RequestBody LoginRequest request) {
        return authService.login(request.email(), request.password());
    }
}

@org.springframework.stereotype.Service
class AuthService {

    private final UserRepository userRepository;
    private final org.springframework.security.crypto.password.PasswordEncoder passwordEncoder;

    AuthService(UserRepository userRepository,
            org.springframework.security.crypto.password.PasswordEncoder passwordEncoder) {
        this.userRepository = userRepository;
        this.passwordEncoder = passwordEncoder;
    }

    RegisterResponse register(String email, String rawPassword, String fullName) {
        if (userRepository.existsByEmail(email)) {
            // 409 theo API contract Day 31 (email da ton tai) - KHONG dung
            // ValidationException (Day 32 anh xa 400, danh cho loi nghiep vu
            // thong thuong); ConflictException rieng anh xa CONFLICT.
            throw new ConflictException("email da duoc su dung");
        }
        UserProfile profile = new UserProfile();
        profile.setFullName(fullName);

        User user = new User();
        user.setEmail(email);
        user.setPasswordHash(passwordEncoder.encode(rawPassword));
        user.setRole("CUSTOMER");
        user.setProfile(profile);
        userRepository.save(user);

        return new RegisterResponse(user.getId(), user.getEmail(), fullName);
    }

    // login(...): xem khoi Login ben duoi - can AuthenticationManager va TokenIssuer.
}

