import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.Authentication;

@org.springframework.stereotype.Service
class AuthService {

    private final AuthenticationManager authenticationManager;
    private final UserRepository userRepository;
    private final TokenIssuer tokenIssuer;

    AuthService(AuthenticationManager authenticationManager,
            UserRepository userRepository, TokenIssuer tokenIssuer) {
        this.authenticationManager = authenticationManager;
        this.userRepository = userRepository;
        this.tokenIssuer = tokenIssuer;
    }

    TokenResponse login(String email, String rawPassword) {
        // Buoc (1): Authentication CHUA xac thuc, mang credentials nguoi dung nhap.
        Authentication unauthenticated = new UsernamePasswordAuthenticationToken(email, rawPassword);

        // Buoc (2)+(3)+(4): AuthenticationManager (ProviderManager) uy quyen cho
        // DaoAuthenticationProvider; DaoAuthenticationProvider goi UserDetailsService
        // lay UserDetails roi dung PasswordEncoder xac minh mat khau tren UserDetails do.
        // That bai se nem AuthenticationException (vi du BadCredentialsException).
        Authentication authenticated = authenticationManager.authenticate(unauthenticated);

        // Buoc (5): thanh cong -> Authentication co principal la UserDetails
        // (CustomUserDetails boc User da persist tu Register, co field id).
        CustomUserDetails principal = (CustomUserDetails) authenticated.getPrincipal();
        User user = userRepository.findById(principal.getId())
            .orElseThrow(() -> new ResourceNotFoundException("user"));

        String accessToken = tokenIssuer.issue(user.getId(), java.util.List.of(user.getRole()));
        return new TokenResponse(accessToken, "Bearer", 3600);
    }
}

import com.nimbusds.jose.jwk.source.ImmutableSecret;
import com.nimbusds.jose.jwk.source.JWKSource;
import com.nimbusds.jose.proc.SecurityContext;
import org.springframework.security.oauth2.jose.jws.MacAlgorithm;
import org.springframework.security.oauth2.jwt.JwsHeader;
import org.springframework.security.oauth2.jwt.JwtClaimsSet;
import org.springframework.security.oauth2.jwt.JwtEncoder;
import org.springframework.security.oauth2.jwt.JwtEncoderParameters;
import org.springframework.security.oauth2.jwt.NimbusJwtEncoder;

import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.time.Instant;
import java.util.List;

@org.springframework.context.annotation.Configuration
class JwtIssuanceConfig {

    // CHI DUNG CHO DEV/DEMO: doc secret tu config (application.properties/bien
    // moi truong), KHONG hardcode/commit len source control o moi truong that -
    // san xuat can mot secret duoc quan ly rieng (vi du secret manager). O nhanh
    // Spring Security 6.5, NimbusJwtEncoder chi co constructor nhan JWKSource
    // duoc ghi nhan - CHUA dung cac static builder (chi co tu nhanh 7.0).
    @org.springframework.beans.factory.annotation.Value("${app.jwt.secret}")
    private String jwtSecret;

    @org.springframework.context.annotation.Bean
    JwtEncoder jwtEncoder() {
        SecretKeySpec key = new SecretKeySpec(jwtSecret.getBytes(StandardCharsets.UTF_8), "HmacSHA256");
        JWKSource<SecurityContext> jwkSource = new ImmutableSecret<>(key);
        return new NimbusJwtEncoder(jwkSource);
    }
}

@org.springframework.stereotype.Component
class TokenIssuer {

    private static final String ISSUER = "spendwise-capstone";
    private static final Duration TTL = Duration.ofHours(1);

    private final JwtEncoder jwtEncoder;

    TokenIssuer(JwtEncoder jwtEncoder) {
        this.jwtEncoder = jwtEncoder;
    }

    String issue(Long userId, List<String> roles) {
        Instant now = Instant.now();
        JwtClaimsSet claims = JwtClaimsSet.builder()
            .issuer(ISSUER)
            .subject(String.valueOf(userId))
            .issuedAt(now)
            .expiresAt(now.plus(TTL))
            .claim("roles", roles)
            .build();

        // Thuat toan ky nam o JWS header, KHONG nam trong claim set: phai khai
        // bao tuong minh HS256 roi truyen ca header lan claims vao encoder.
        // JwtEncoderParameters.from(claims) (mot tham so) de JWS header = null,
        // tuc khong khai bao thuat toan nao ca.
        JwsHeader header = JwsHeader.with(MacAlgorithm.HS256).build();
        return jwtEncoder.encode(JwtEncoderParameters.from(header, claims)).getTokenValue();
    }
}

