@org.springframework.context.annotation.Configuration
// Bat Method Security (xem lai ly thuyet o Day 23/day23-blk-2) - THIEU annotation
// nay thi moi @PreAuthorize trong du an (day33-blk-12, day34-blk-6) bi Spring
// BO QUA HOAN TOAN, khong chan gi ca du code annotation van con nguyen.
@org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity
class SecurityConfig {

    @org.springframework.beans.factory.annotation.Value("${app.jwt.secret}")
    private String jwtSecret;

    // Dung LAI dung secret voi JwtEncoder o tren de xac thuc chu ky JWT tu
    // phat hanh - KHONG goi jwks_url/authorization server ben ngoai nao.
    @org.springframework.context.annotation.Bean
    org.springframework.security.oauth2.jwt.JwtDecoder jwtDecoder() {
        javax.crypto.spec.SecretKeySpec key = new javax.crypto.spec.SecretKeySpec(
            jwtSecret.getBytes(java.nio.charset.StandardCharsets.UTF_8), "HmacSHA256");
        return org.springframework.security.oauth2.jwt.NimbusJwtDecoder.withSecretKey(key).build();
    }

    // Du an quy uoc ROLE_ (khong phai SCOPE_ mac dinh cua framework - xem khoi
    // important ben duoi): doc claim "roles" da nhung vao JWT luc phat hanh,
    // sinh GrantedAuthority voi tien to ROLE_ thay vi doc claim scope mac dinh.
    @org.springframework.context.annotation.Bean
    org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter jwtAuthenticationConverter() {
        var authorities = new org.springframework.security.oauth2.server.resource.authentication.JwtGrantedAuthoritiesConverter();
        authorities.setAuthorityPrefix("ROLE_");
        authorities.setAuthoritiesClaimName("roles");

        var converter = new org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter();
        converter.setJwtGrantedAuthoritiesConverter(authorities);
        return converter;
    }

    @org.springframework.context.annotation.Bean
    org.springframework.security.web.SecurityFilterChain filterChain(
            org.springframework.security.config.annotation.web.builders.HttpSecurity http,
            org.springframework.security.oauth2.jwt.JwtDecoder jwtDecoder,
            org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter jwtAuthenticationConverter) throws Exception {
        http.authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/auth/register", "/api/auth/login").permitAll()
                // API contract Day 31: GET category/product khong yeu cau dang nhap
                // (Auth: Khong); chi POST/PUT/DELETE moi can ROLE_ADMIN qua @PreAuthorize.
                .requestMatchers(org.springframework.http.HttpMethod.GET, "/api/categories/**", "/api/products/**").permitAll()
                .anyRequest().authenticated())
            .oauth2ResourceServer(oauth2 -> oauth2.jwt(jwt -> jwt
                .decoder(jwtDecoder)
                .jwtAuthenticationConverter(jwtAuthenticationConverter)));
        return http.build();
    }
}
